<script setup>
import {ref,onMounted} from 'vue'
import {api,post,portLabel,formatTimestamp} from './quotationApi'
const props=defineProps({user:Object})
const emit=defineEmits(['drafts'])
const batches=ref([]),detail=ref(null),error=ref(''),message=ref(''),busy=ref(false),reason=ref(''),selected=ref(''),actions=ref({}),targets=ref({})
const fieldLabels={origin_port_id:'起运港',destination_port_id:'目的港',route_id:'航线',carrier_id:'船公司',source_series_id:'报价系列',service_key:'服务标识',service_kind:'直达／中转',path_text:'运输路径',fee_basis:'费用口径',currency:'币种',sailing:'船期',transit_days:'航程天数',remark:'备注',valid_from:'有效期起',valid_to:'有效期止',validity_basis:'适用依据',validity_original:'有效期原文',included_fees:'已含费用',extra_fees:'另计费用',unknown_fees:'待确认费用',conditions:'适用条件',conditions_confirmed:'条件已确认',origin_confirmed:'起运港已确认',prices:'箱型价格','prices.20GP':'20GP价格','prices.40GP':'40GP价格','prices.40HQ':'40HQ价格'}
const show=value=>value===true?'已确认':value===false?'未确认':value==='direct'?'直达':value==='transshipment'?'中转':typeof value==='object'?Object.entries(value||{}).map(([k,v])=>`${k}：${v??'缺价'}`).join('；'):value||'（空白）'
const labels={draft:'草稿',pending:'待审批',approved:'已入库',rejected:'已驳回',withdrawn:'已撤回',new:'新增',modified:'修改',unchanged:'无变化',duplicate:'批内重复'}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){batches.value=(await api('/api/review/batches')).items}
async function open(id){detail.value=await api(`/api/review/batches/${id}`);selected.value=id;actions.value={};targets.value={};reason.value='';for(const r of detail.value.rows){actions.value[r.id]=JSON.parse(r.field_actions_json);targets.value[r.id]=r.target_quote_id||''}}
async function resolve(row,included=row.included){const t=detail.value.targets.find(t=>t.quote_id===targets.value[row.id]);await post(`/api/review/rows/${row.id}`,{revision:row.revision,included:!!included,target_quote_id:t?.quote_id||null,expected_version:t?.version||null,field_actions:actions.value[row.id]||{}},'PUT');await open(selected.value);await load()}
async function submit(){await post(`/api/review/batches/${selected.value}/submit`,{token:detail.value.preview.token});message.value='已提交，报价尚未入库';await open(selected.value);await load()}
async function decision(value){const sid=detail.value.submissions[0].id;await post(`/api/review/submissions/${sid}/decision`,{operation_key:crypto.randomUUID(),decision:value,reason:reason.value});message.value=value==='approved'?'整批审批通过，已入库':'已驳回，可修改后重提';await open(selected.value);await load()}
async function withdraw(){await post(`/api/review/batches/${selected.value}/withdraw`,{});await open(selected.value);await load()}
const editable=()=>['draft','rejected','withdrawn'].includes(detail.value?.batch.status)
onMounted(()=>run(load))
</script>
<template>
<div class="section-heading"><div><h2>报价差异与审批</h2><p>核对来源与每项变化，整批审批后发布。未出现的旧报价不会被删除。</p></div><button @click="emit('drafts')">返回草稿校对</button><button :disabled="busy" @click="run(load)">刷新批次</button></div>
<p class="notice">当前操作员：{{user?.username}} · {{user?.role==='admin'?'管理员，可审批自己提交的批次':'业务人员，提交后由管理员审批'}}。</p>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
<div class="review-layout"><aside><button v-for="b in batches" :key="b.id" class="review-batch" :disabled="busy" @click="run(()=>open(b.id))">{{labels[b.status]}} · {{b.row_count}}行<br><small>{{b.id.slice(0,10)}} · {{formatTimestamp(b.created_at)}}</small></button><p v-if="!batches.length">暂无报价草稿，请先人工录入或导入Excel。</p></aside>
<section v-if="detail" class="review-detail"><h3>批次 {{selected.slice(0,10)}} · {{labels[detail.batch.status]}}</h3>
<template v-if="editable()"><p>取消勾选的问题行会在提交时移到独立草稿。空白字段默认保留旧值；确需清空请明确选择。</p>
<div v-for="r in detail.rows" :key="r.id" class="review-scope"><label><input type="checkbox" :checked="r.included" :disabled="busy" @change="run(()=>resolve(r,$event.target.checked))">纳入本次提交 · {{r.id.slice(0,8)}}</label>
<label>明确修订目标<select v-model="targets[r.id]"><option value="">自动匹配同口径同有效期</option><option v-for="t in detail.targets" :key="t.quote_id" :value="t.quote_id">{{t.data.service_key}} · {{t.data.currency}} · {{t.data.valid_from}}～{{t.data.valid_to}} · {{t.quote_id.slice(0,8)}} v{{t.version}}</option></select></label>
<details><summary>逐字段处理方式</summary><div v-for="field in [...Object.keys(detail.preview.items.find(i=>i.row_id===r.id)?.data||{}).filter(k=>!['prices','zero_confirmed','manual_note'].includes(k)),'prices.20GP','prices.40GP','prices.40HQ']" :key="field"><label>{{fieldLabels[field]||field}} <select v-model="actions[r.id][field]"><option :value="undefined">默认：空白保留旧值</option><option value="keep">保留旧值</option><option value="set">使用本次填写值</option><option value="clear">明确清空</option></select></label></div></details><button :disabled="busy" @click="run(()=>resolve(r))">保存目标与字段处理，重新对比</button></div></template>
<article v-for="item in detail.preview.items" :key="item.row_id" class="review-card"><h3>{{labels[item.kind]}} · {{item.row_id.slice(0,8)}}</h3><p>{{portLabel(item.display.origin)}} → {{portLabel(item.display.destination)}}</p><p>{{item.display.carrier?.name}} · {{item.display.supplier?.name}} / {{item.display.series?.name}} · {{item.data.service_key}} · {{item.data.currency}}</p><p>{{item.data.valid_from}} ～ {{item.data.valid_to}} · {{show(item.data.prices)}}</p><ul v-if="item.problems.length" class="error"><li v-for="p in item.problems" :key="p">{{p}}</li></ul><table v-if="Object.keys(item.changes).length"><thead><tr><th>字段</th><th>原值</th><th>新值</th></tr></thead><tbody><tr v-for="(change,field) in item.changes" :key="field"><td>{{fieldLabels[field]||field}}</td><td>{{show(change.before)}}</td><td>{{show(change.after)}}</td></tr></tbody></table><details><summary>完整报价字段</summary><p v-for="(value,key) in item.data" :key="key" v-show="!key.endsWith('_id') && key!=='zero_confirmed'"><b>{{fieldLabels[key]|| (key==='manual_note'?'报价依据':key)}}：</b>{{show(value)}}</p></details><p v-if="item.duplicate_of">重复行，合并到 {{item.duplicate_of.slice(0,8)}}</p><details v-if="item.target"><summary>原报价与原件依据（版本{{item.target.version}}）</summary><p v-for="(v,k) in item.target.data" :key="k" v-show="!k.endsWith('_id') && k!=='zero_confirmed'">{{fieldLabels[k]||k}}：{{show(v)}}</p><p v-for="e in item.target.evidence" :key="e.id">{{e.original_name}} {{e.worksheet}} {{e.cell_range}} {{e.manual_note}} <a v-if="e.file_id" :href="`/api/uploads/files/${e.file_id}/original`" download>下载原件核对</a></p></details><details><summary>本次原件与报价依据</summary><p v-for="e in item.evidence" :key="e.id">{{e.original_name}} {{e.worksheet}} {{e.cell_range}} {{e.manual_note}} <a v-if="e.file_id" :href="`/api/uploads/files/${e.file_id}/original`" download>下载原件核对</a></p><p>{{item.data.manual_note}}</p></details></article>
<button v-if="editable()" :disabled="busy||!detail.preview.can_submit" @click="run(submit)">确认差异，提交审批</button>
<template v-if="detail.batch.status==='pending'"><p>提交内容已锁定。审批通过时会重新核对报价版本；冲突需撤回后重新提交。</p><button :disabled="busy" @click="run(withdraw)">撤回重新编辑</button><label v-if="user?.role==='admin'">审批备注／驳回理由<textarea v-model="reason" maxlength="2000"/></label><button v-if="user?.role==='admin'" :disabled="busy" @click="run(()=>decision('approved'))">整批审批通过并入库</button><button v-if="user?.role==='admin'" :disabled="busy||!reason.trim()" @click="run(()=>decision('rejected'))">驳回</button></template>
<details v-if="detail.submissions.length"><summary>提交与审批历史（冻结快照）</summary><article v-for="s in detail.submissions" :key="s.id"><p>{{formatTimestamp(s.submitted_at)}} · {{labels[s.decision]||'已提交'}} · {{s.reason}}</p><p>提交编号 {{s.id.slice(0,10)}} · 提交人 {{s.submitted_by}} · 审批人 {{s.actor_id||'待审批'}}</p><article v-for="i in s.snapshot.items" :key="i.row_id"><b>{{labels[i.kind]}} · {{portLabel(i.display.destination)}} · {{i.display.carrier?.name}} · {{i.display.series?.name}}</b><p>{{i.data.valid_from}} ～ {{i.data.valid_to}} · {{i.data.currency}} · {{show(i.data.prices)}}</p><p v-for="(v,k) in i.changes" :key="k">{{fieldLabels[k]||k}}：{{show(v.before)}} → {{show(v.after)}}</p></article></article></details>
</section></div>
</template>
<style scoped>
.review-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:24px}.review-batch{display:block;width:100%;text-align:left;margin-bottom:10px;white-space:normal}.review-card,.review-scope{padding:18px;border:1px solid #d9e3eb;border-radius:10px;margin:14px 0;background:white}.review-detail{min-width:0}.review-detail label{display:block;margin:8px 0}.review-detail select,.review-detail textarea{max-width:100%;padding:6px}.review-detail table{width:100%;border-collapse:collapse}.review-detail td,.review-detail th{padding:8px;border:1px solid #ddd;overflow-wrap:anywhere}.review-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto}.review-detail button{margin:6px}.error{color:#a32424}@media(max-width:800px){.review-layout{grid-template-columns:1fr}}
</style>
